package dev.slithergoh.pixelmonradar.client;
import com.mojang.blaze3d.vertex.PoseStack;import net.minecraft.client.Minecraft;import net.minecraft.client.gui.GuiGraphics;import net.neoforged.api.distmarker.Dist;import net.neoforged.bus.api.SubscribeEvent;import net.neoforged.fml.common.EventBusSubscriber;import net.neoforged.neoforge.client.event.RenderGuiEvent;import org.joml.AxisAngle4f;import org.joml.Quaternionf;import java.util.*;
@EventBusSubscriber(modid="pixelmonradar",value=Dist.CLIENT)public final class RadarHud{
 @SubscribeEvent public static void render(RenderGuiEvent.Post e){if(!RadarSettings.hudEnabled)return;Minecraft mc=Minecraft.getInstance();if(mc.player==null||mc.level==null||mc.screen!=null)return;List<PokemonInfo>all=PokemonScanner.scan();ArrayList<PokemonInfo>list=new ArrayList<>(all);list.sort(Comparator.comparingInt(RadarHud::priority).reversed().thenComparingDouble(PokemonInfo::distance));GuiGraphics g=e.getGuiGraphics();int shown=Math.min(4,list.size()),w=154,h=21+shown*19+(list.size()>shown?10:0);g.fill(5,5,5+w,5+h,0xA80A1218);g.fill(5,5,8,5+h,0xD047BCE8);g.drawString(mc.font,"ATLAS",13,10,0xFFF4F8FA,true);g.drawString(mc.font,list.size()+" nearby",5+w-52,10,0xFF8DB1C1,false);int y=25;for(int i=0;i<shown;i++){PokemonInfo p=list.get(i);boolean tr=p.entityId()==RadarSettings.trackedEntityId;int ac=accent(p);if(tr)g.fill(10,y-2,5+w-5,y+16,0x99245A49);if(p.sprite()!=null)g.blit(p.sprite(),12,y,0,0,15,15,15,15);String n=p.name();if(mc.font.width(n)>72)n=mc.font.plainSubstrByWidth(n,69)+"…";g.drawString(mc.font,n,31,y,p.rare()?ac:0xFFE8EEF1,true);g.drawString(mc.font,Math.round(p.distance())+"m",5+w-31,y,0xFF9FB1B9,false);if(p.shiny())g.drawString(mc.font,"★",5+w-43,y,0xFF62FFFF,true);y+=19;}if(list.size()>shown)g.drawString(mc.font,"+"+(list.size()-shown)+" more • R details",13,y,0xFF718995,false);for(PokemonInfo p:list)if(p.entityId()==RadarSettings.trackedEntityId){renderTracker(g,mc,p);break;}}
 private static void renderTracker(GuiGraphics g,Minecraft mc,PokemonInfo p){double dx=p.pos().getX()+.5-mc.player.getX(),dz=p.pos().getZ()+.5-mc.player.getZ();double target=Math.toDegrees(Math.atan2(-dx,dz)),rel=wrap(target-mc.player.getYRot());int cx=g.guiWidth()/2,w=190,left=cx-w/2;int ac=accent(p);g.fill(left,6,left+w,44,0xC90A1218);g.fill(left,6,left+w,8,ac);if(p.sprite()!=null)g.blit(p.sprite(),left+7,11,0,0,27,27,27,27);g.drawString(mc.font,p.name()+"  Lv."+p.level(),left+40,12,p.rare()?ac:0xFFFFFFFF,true);g.drawString(mc.font,Math.round(p.distance())+"m • "+direction(mc,p)+" • Y "+p.pos().getY(),left+40,25,0xFF9DB2BC,false);PoseStack ps=g.pose();ps.pushPose();ps.translate(left+w-18,25,0);ps.mulPose(new Quaternionf(new AxisAngle4f((float)Math.toRadians(-rel),0,0,1)));float pulse=(float)(1.0+Math.sin(System.currentTimeMillis()/170.0)*.05);ps.scale(pulse,pulse,1);g.fill(-2,-10,2,7,ac);g.fill(-6,-7,7,-3,ac);ps.popPose();}
 private static int priority(PokemonInfo p){if(p.shiny())return 100;if(p.legendary()||p.mythical())return 90;if(p.ultraBeast()||p.paradox())return 80;if(p.boss())return 70;return 0;}private static int accent(PokemonInfo p){if(p.shiny())return 0xFF62FFFF;if(p.legendary()||p.mythical())return 0xFFFFB64F;if(p.ultraBeast()||p.paradox())return 0xFFB987FF;if(p.boss())return 0xFFFF6666;return 0xFF4EB7DD;}private static String direction(Minecraft mc,PokemonInfo p){double dx=p.pos().getX()+.5-mc.player.getX(),dz=p.pos().getZ()+.5-mc.player.getZ();double a=(Math.toDegrees(Math.atan2(-dx,dz))+360)%360;String[]d={"N","NE","E","SE","S","SW","W","NW"};return d[(int)Math.round(a/45)%8];}private static double wrap(double a){while(a<=-180)a+=360;while(a>180)a-=360;return a;}}
